import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry sigmoid_f32_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 n
)
{
    .reg .pred %p<2>;
    .reg .b32 %r<4>;
    .reg .b64 %rd<4>;
    .reg .f32 %f<8>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r1, [n];

    mov.u32 %r0, %tid.x;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mad.lo.u32 %r2, %r2, %r3, %r0;

    setp.ge.u32 %p1, %r2, %r1;
    @%p1 bra DONE;

    cvt.u64.u32 %rd3, %r2;
    shl.b64 %rd3, %rd3, 2;
    add.s64 %rd1, %rd1, %rd3;
    add.s64 %rd2, %rd2, %rd3;

    ld.global.f32 %f1, [%rd1];
    neg.f32 %f2, %f1;
    mov.f32 %f3, 0f3FB8AA3B;
    mul.f32 %f4, %f2, %f3;
    ex2.approx.f32 %f5, %f4;
    add.f32 %f6, %f5, 0f3F800000;
    rcp.approx.f32 %f7, %f6;
    st.global.f32 [%rd2], %f7;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sigmoid_f32_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        y = torch.empty(x.shape, dtype=x.dtype, device=x.device)
        n = x.numel()
        if n == 0:
            return y

        block_x = 256
        grid_x = (n + block_x - 1) // block_x

        _get_ptx_module().launch(
            "sigmoid_f32_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, y, u32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

